        require(contract_address != address(0x0));
        require(contract_address != address(c));
        require(tos.length > 0);
        require(vs.length > 0);
        require(tos.length == vs.length);

        uint balBefore = address(this).balance;
        uint cBalBefore = address(c).balance;

        bool ok;
        bool reverted;
        try c.transfer(contract_address, tos, vs) returns (bool _ok) {
            ok = _ok;
            reverted = false;
        } catch {
            ok = false;
            reverted = true;
        }

        uint balAfter = address(this).balance;
        uint cBalAfter = address(c).balance;

        uint sumVs = 0;
        for (uint i = 0; i < vs.length; i++) {
            sumVs += vs[i];
        }

        assert((!reverted && ok) || (reverted && !ok && balAfter >= cBalAfter && balAfter - cBalAfter >= balBefore - cBalBefore));
    }

    receive() external payable {}
}

